class WeatherRequest(BaseModel):
    location: str
    days: int = 7
    units: str = "Farenheit"


@app.post("/weather")
async def weather(req: WeatherRequest, res: Response):
    weather_forecast = {
        "location": req.location,
        "temperature": [],
        "units": req.units,
    }
    for i in range(req.days):
        min_temp = random.randrange(50, 90)
        max_temp = random.randrange(min_temp + 5, min_temp + 20)
        if req.units.lower() == "celsius" or req.units.lower() == "c":
            min_temp = (min_temp - 32) * 5.0 / 9.0
            max_temp = (max_temp - 32) * 5.0 / 9.0
        weather_forecast["temperature"].append(
            {
                "date": str(date.today() + timedelta(days=i)),
                "temperature": {"min": min_temp, "max": max_temp},
                "units": req.units,
                "query_time": str(datetime.now(timezone.utc)),
            }
        )

    return weather_forecast


class DefaultTargetRequest(BaseModel):
    messages: list = []


@app.post("/default_target")
async def default_target(req: DefaultTargetRequest, res: Response):
    logger.info(f"Received messages: {req.messages}")
    resp = {
        "choices": [
            {
                "message": {
                    "role": "assistant",
                    "content": "I can help you with weather forecast",
                },
            }
        ],
        "model": "api_server",
    }
    logger.info(f"sending response: {json.dumps(resp)}")
    return resp

#!/usr/bin/env python3
"""Interactive chat with a model through Plano using the OpenAI SDK."""

import sys
from openai import OpenAI

client = OpenAI(base_url="http://localhost:12000/v1", api_key="unused")


def run_chat(model):
    print(f"Chatting with {model} via Plano (Ctrl+C to quit)\n")
    history = []
    while True:
        try:
            user_input = input("you> ")
        except (KeyboardInterrupt, EOFError):
            print("\nbye")
            break
        if not user_input.strip():
            continue

        history.append({"role": "user", "content": user_input})

        stream = client.responses.create(model=model, input=history, stream=True)
        print(f"{model}> ", end="", flush=True)
        full = ""
        for event in stream:
            if event.type == "response.output_text.delta":
                print(event.delta, end="", flush=True)
                full += event.delta
        print()

        history.append({"role": "assistant", "content": full})


if __name__ == "__main__":
    model = sys.argv[1] if len(sys.argv) > 1 else "gpt-5.2"
    run_chat(model)

